// Kimi 2.7.2 print, ACP and main-agent wire shapes. Identifiers and content are
// generated by this local process. It never makes a model request.
import { createHash, randomUUID } from 'node:crypto'
import { appendFileSync, linkSync, mkdirSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { hostname } from 'node:os'
import { basename, join } from 'node:path'
import { createInterface } from 'node:readline'
import { setTimeout } from 'node:timers/promises'

const args = process.argv.slice(2)
const session = 'session_' + randomUUID()
const cwd = process.cwd()
const root = process.env.KIMI_CODE_HOME
const key = 'wd_' + basename(cwd).toLowerCase() + '_' + createHash('sha256').update(cwd).digest('hex').slice(0, 12)
const folder = join(root, 'sessions', key, session, 'agents', 'main')
const wire = join(folder, 'wire.jsonl')
const locks = join(root, 'locks', 'sessions')
mkdirSync(folder, { recursive: true })
writeFileSync(wire, JSON.stringify({ type: 'metadata', protocol_version: '1.5', created_at: Date.now(), min_protocol_version: '1.5' }) + '\n')

function failedTurn(input, mode, turnId) {
  const time = Date.now()
  const error = mode === 'rate' ? { code: 'provider.rate_limit', name: 'APIProviderRateLimitError', retryable: true } :
    { code: 'provider.api_error', name: 'APIProviderQuotaExhaustedError', retryable: false }
  const entries = [
    { type: 'turn.prompt', agentId: 'main', turnId, time, input },
    { type: 'turn.ended', agentId: 'main', turnId, reason: 'failed', time, error: {
      ...error, message: 'private account detail', details: { statusCode: 429, requestId: 'private-provider-id' } } },
  ]
  appendFileSync(wire, entries.map(entry => JSON.stringify(entry)).join('\n') + '\n')
}

if (args[0] === 'acp') {
  let mode
  for await (const line of createInterface({ input: process.stdin })) {
    const { id, method, params } = JSON.parse(line)
    const reply = (result) => console.log(JSON.stringify({ jsonrpc: '2.0', id, result }))
    if (method === 'initialize') reply({ protocolVersion: 1 })
    else if (method === 'session/new') {
      // Same question, earlier turn: an ACP resume can carry all of this history.
      failedTurn([{ type: 'text', text: 'L'.repeat(140000) }], 'quota', 0)
      reply({ sessionId: session })
    } else if (method === 'session/set_config_option') {
      if (params.configId === 'model') mode = params.value.split('/').at(-1)
      reply({})
    } else if (method === 'session/set_mode') reply({})
    else if (method === 'session/prompt') {
      if (['stale', 'replaced', 'ambiguous'].includes(mode)) console.error('private native diagnostic')
      if (mode === 'replaced') { renameSync(wire, wire + '.earlier'); writeFileSync(wire, '') }
      if (mode !== 'stale') failedTurn(params.prompt, mode, 1)
      if (mode === 'ambiguous') failedTurn(params.prompt, mode, 2)
      if (mode === 'partial') {
        console.log(JSON.stringify({ jsonrpc: '2.0', method: 'session/update', params: {
          sessionId: session, update: { sessionUpdate: 'agent_message_chunk', content: { type: 'text', text: 'incomplete' } } } }))
      }
      reply({ stopReason: 'end_turn' })
    }
  }
} else {
  const mode = args[args.indexOf('--model') + 1].split('/').at(-1)
  if (mode === 'success') {
    console.log(JSON.stringify({ role: 'assistant', content: [{ type: 'text', text: 'native success' }] }))
    console.log(JSON.stringify({ role: 'meta', type: 'session.resume_hint', session_id: session }))
    process.exit(0)
  }
  const lock = join(locks, session + '.lock')
  const pid = mode === 'foreign' ? process.ppid : process.pid
  const staged = lock + '.tmp-' + pid + '-' + randomUUID()
  writeFileSync(staged, JSON.stringify({ version: 1, hostname: hostname(), startedAt: Date.now(), pid }))
  linkSync(staged, lock)
  rmSync(staged)
  const prompt = args[args.indexOf('--prompt') + 1]
  failedTurn([{ type: 'text', text: mode === 'wrong-prompt' ? 'an unrelated turn' : prompt }], mode, 0)
  // The recorded failed print held its native lease for the duration of the turn.
  await setTimeout(1600)
  rmSync(lock)
  console.error('error: failed to run prompt: Prompt turn ended with reason: failed')
  process.exitCode = 1
}
